// Cross-check against the Python reference (fixtures/*.json, generated by
// `uv run python -m model.fixtures --year`).
//
// - no battery and rule-based: same arithmetic, must match to 1e-6 EUR
// - optimised: the DP must be within 1% of the annual energy cost (supply +
//   feed-in + energy tax) of the MILP result. The scale is the larger in
//   absolute value of the no-battery and the optimised energy cost, so the
//   test stays meaningful when one of them is close to zero. The 4-day
//   synthetic cases get an extra 0.01 EUR per day: the interpolation error is
//   a few tenths of a cent per day regardless of how small the bill is.

import { afterAll, describe, expect, it } from "vitest";
import { run } from "../src/model/scenario";
import { type Fixture, fixtureInputs, readJson } from "./helpers";

const small = readJson<Fixture[]>("fixtures/small_cases.json");
const year = readJson<Fixture[]>("fixtures/year_cases.json");
const report: string[] = [];

function check(fx: Fixture) {
  const inputs = fixtureInputs(fx);
  for (const s of ["none", "rule"] as const) {
    const r = run(s, fx.tariff, inputs, fx.battery, fx.lookahead_days);
    expect(r.total).toBeCloseTo(fx.expected[s].total, 6);
    expect(r.regime).toBe(fx.expected[s].regime);
  }
  const t0 = performance.now();
  const dp = run("optimal", fx.tariff, inputs, fx.battery, fx.lookahead_days);
  const ms = performance.now() - t0;
  const lp = fx.expected.optimal;
  const scale = Math.max(Math.abs(fx.expected.none.energy_cost), Math.abs(lp.energy_cost));
  const gap = dp.total - lp.total;
  const saving = fx.expected.none.total - lp.total;
  report.push(
    `| ${fx.name} | ${fx.expected.none.total.toFixed(2)} | ${lp.total.toFixed(2)} | ${dp.total.toFixed(2)} | ` +
      `${gap.toFixed(2)} | ${((100 * gap) / scale).toFixed(2)}% | ` +
      `${saving > 0.01 ? ((100 * gap) / saving).toFixed(1) + "%" : "-"} | ${ms.toFixed(0)} |`,
  );
  const floor = "year" in fx.inputs ? 0 : 0.01 * inputs.dayStarts.length;
  expect(Math.abs(gap)).toBeLessThanOrEqual(0.01 * scale + floor + 1e-6);
}

describe("small fixtures", () => {
  for (const fx of small) it(fx.name, () => check(fx));
});

describe("full-year fixtures (2025 prices)", () => {
  for (const fx of year) it(fx.name, () => check(fx));
});

afterAll(() => {
  console.log(
    [
      "| case | no battery | MILP | DP | DP - MILP (EUR) | % of energy cost | % of saving | DP ms |",
      "|---|---|---|---|---|---|---|---|",
      ...report,
    ].join("\n"),
  );
});
